import { balanceDue } from './payments.js';
import { daysBetween } from './dates.js';
import { roundCents } from './money.js';
import { invoiceTotals } from './invoices.js';

/**
 * Generate a report of overdue invoices.
 * @param {Array<any>} invoices - All invoices
 * @param {string} asOf - YYYY-MM-DD format, cutoff date
 * @returns {Array<{ number: string, customerId: string, dueDate: string, daysOverdue: number, due: number }>}
 */
export function overdueInvoices(invoices, asOf) {
  return invoices
    .filter((inv) =>
      (inv.status === 'issued' || inv.status === 'partially_paid') &&
      inv.dueDate < asOf
    )
    .map((inv) => ({
      number: inv.number,
      customerId: inv.customerId,
      dueDate: inv.dueDate,
      daysOverdue: daysBetween(inv.dueDate, asOf),
      due: balanceDue(inv),
    }))
    .sort((a, b) => b.daysOverdue - a.daysOverdue);
}

/**
 * Generate a VAT summary report.
 * @param {Array<any>} invoices - All invoices
 * @returns {Array<{ rate: number, base: number, vat: number }>} sorted by rate descending
 */
export function vatSummary(invoices) {
  const rateBuckets = {};

  // Iterate through all invoices with status issued, partially_paid, or paid
  for (const invoice of invoices) {
    if (!['issued', 'partially_paid', 'paid'].includes(invoice.status)) {
      continue;
    }

    // Process each line in the invoice
    for (const line of invoice.lines) {
      const rate = line.vatRate;
      const lineAmount = line.qty * line.unitPrice;
      const discountPercent = line.discountPercent ?? 0;
      const discountAmount = roundCents(lineAmount * discountPercent / 100);
      const base = lineAmount - discountAmount;
      const vat = roundCents(base * rate / 100);

      // Add to bucket for this rate
      if (!rateBuckets[rate]) {
        rateBuckets[rate] = { rate, base: 0, vat: 0 };
      }
      rateBuckets[rate].base += base;
      rateBuckets[rate].vat += vat;
    }
  }

  // Convert buckets to array and sort by rate descending
  return Object.values(rateBuckets).sort((a, b) => b.rate - a.rate);
}

/**
 * Calculate late fee for an invoice.
 * @param {{ status: string, dueDate?: string }} invoice
 * @param {string} asOf - YYYY-MM-DD format, evaluation date
 * @returns {number} - late fee in cents, 0 if not overdue
 */
export function lateFee(invoice, asOf) {
  // Only charged on issued and partially_paid invoices
  if (!['issued', 'partially_paid'].includes(invoice.status)) {
    return 0;
  }

  // Must have a dueDate
  if (!invoice.dueDate) {
    return 0;
  }

  // Check if overdue (dueDate < asOf)
  if (invoice.dueDate >= asOf) {
    return 0;
  }

  // Calculate days overdue
  const daysOverdue = daysBetween(invoice.dueDate, asOf);

  // Get amount still due
  const due = balanceDue(invoice);

  // Calculate late fee: 0.04% per day = 0.0004 per day
  return roundCents(due * 0.0004 * daysOverdue);
}

