 * Calculate late fee for an invoice.
 * @param {{ status: string, dueDate?: string }} invoice
 * @param {string} asOf - YYYY-MM-DD format, evaluation date
 * @returns {number} - late fee in cents, 0 if not overdue
 */
export function lateFee(invoice, asOf) {
  // Only charged on issued and partially_paid invoices
  if (!['issued', 'partially_paid'].includes(invoice.status)) {
    return 0;
  }

  // Must have a dueDate
  if (!invoice.dueDate) {
    return 0;
  }

  // Check if overdue (dueDate < asOf)
  if (invoice.dueDate >= asOf) {
    return 0;
  }

  // Calculate days overdue
  const daysOverdue = daysBetween(invoice.dueDate, asOf);

  // Get amount still due
  const due = balanceDue(invoice);

  // Calculate late fee: 0.04% per day = 0.0004 per day
  return roundCents(due * 0.0004 * daysOverdue);
}

/**
 * Generate a dashboard with key metrics.
 * @param {Array<any>} invoices - All invoices
 * @param {string} asOf - YYYY-MM-DD format, cutoff date
 * @returns {{ counts: { draft: number, issued: number, partially_paid: number, paid: number }, outstanding: number, overdue: { count: number, amount: number }, topCustomers: Array<{ customerId: string, due: number }> }}
 */
export function dashboard(invoices, asOf) {
  const counts = {
    draft: 0,
    issued: 0,
    partially_paid: 0,
    paid: 0,
  };

  let outstanding = 0;
  const customerDues = {};

  for (const invoice of invoices) {
    counts[invoice.status] = (counts[invoice.status] || 0) + 1;

    if (invoice.status === 'issued' || invoice.status === 'partially_paid') {
      const due = balanceDue(invoice);
      outstanding += due;
      customerDues[invoice.customerId] = (customerDues[invoice.customerId] || 0) + due;
    }
  }

  const overdue = overdueInvoices(invoices, asOf);
  const overdueAmount = overdue.reduce((sum, inv) => sum + inv.due, 0);

  const topCustomers = Object.entries(customerDues)
    .map(([customerId, due]) => ({ customerId, due }))
    .sort((a, b) => b.due - a.due)
    .slice(0, 3);

  return {
    counts,
    outstanding,
    overdue: { count: overdue.length, amount: overdueAmount },
    topCustomers,
  };
}

