test('lateFee: respects EOM terms', () => {
  const invoice = createIssuedInvoice('C-001', '2026-10-05', 'EOM');
  // Due date is 2026-10-31, check on 2026-11-15 (15 days overdue)
  const fee = lateFee(invoice, '2026-11-15');
  // Should charge fee for days overdue
  assert.ok(fee > 0);
