  const invoice = issueInvoice(created.value, []).value;
  const result = vatSummary([invoice]);
  assert.equal(result.length, 2);
  assert.equal(result[0].rate, 21);
  assert.equal(result[1].rate, 9);
});

test('vatSummary: calculates VAT correctly per rate', () => {
  const created = createInvoice({
    customerId: 'C-002', // standard tier, 0% discount
    issueDate: '2026-10-01',
    lines: [
      { sku: 'PHOTO-LIC', qty: 1 }, // 21% VAT
    ],
  });
  const invoice = issueInvoice(created.value, []).value;
  const result = vatSummary([invoice]);
  // base = 996, vat = 996 * 21 / 100 = 209.16 → 209
  assert.equal(result[0].vat, 209);
});

test('vatSummary: preserves all required fields', () => {
  const invoice = createIssuedInvoice('C-001', '2026-10-01');
  const result = vatSummary([invoice]);
  assert.equal(result.length, 1);
  const entry = result[0];
  assert.ok('rate' in entry);
  assert.ok('base' in entry);
  assert.ok('vat' in entry);
});

test('vatSummary: base and vat are integers', () => {
  const invoice = createIssuedInvoice('C-001', '2026-10-01');
  const result = vatSummary([invoice]);
  assert.equal(Number.isInteger(result[0].base), true);
  assert.equal(Number.isInteger(result[0].vat), true);
});

test('vatSummary: does not mutate input array', () => {
  const invoice = createIssuedInvoice('C-001', '2026-10-01');
  const invoices = [invoice];
  const original = JSON.stringify(invoices);
  vatSummary(invoices);
  assert.equal(JSON.stringify(invoices), original);
});

test('vatSummary: handles zero VAT rate', () => {
  const created = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [
      { sku: 'WORKSHOP-DAY', qty: 1 }, // 0% VAT
    ],
  });
  const invoice = issueInvoice(created.value, []).value;
  const result = vatSummary([invoice]);
  assert.ok(result.some(r => r.rate === 0));
  const zeroRate = result.find(r => r.rate === 0);
