test('vatSummary: aggregates across customer boundaries', () => {
  const inv1 = createIssuedInvoice('C-001', '2026-10-01'); // gold 5% discount
  const inv2 = createIssuedInvoice('C-002', '2026-10-01'); // standard 0% discount
  const result = vatSummary([inv1, inv2]);
