test('dashboard: counts invoices by status', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'PHOTO-LIC', qty: 1 }],
  }).value;
  const issued = issueInvoice(draft, []).value;
  const partial = recordPayment(issued, { amount: 500, date: '2026-10-02' }).value;
  const paid = recordPayment(partial, { amount: 645, date: '2026-10-03' }).value;
  const draft2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-02',
    lines: [{ sku: 'PHOTO-LIC', qty: 1 }],
  }).value;

  const result = dashboard([draft, issued, partial, paid, draft2], '2026-10-07');
  assert.equal(result.counts.draft, 2);
  assert.equal(result.counts.issued, 1);
  assert.equal(result.counts.partially_paid, 1);
  assert.equal(result.counts.paid, 1);
});

test('dashboard: calculates outstanding amount', () => {
  const inv1 = createIssuedInvoice('C-001', '2026-10-01');
  const inv2Partial = recordPayment(
    createIssuedInvoice('C-002', '2026-10-02'),
    { amount: 500, date: '2026-10-02' }
  ).value;
  const inv3 = recordPayment(
    createIssuedInvoice('C-003', '2026-10-03'),
    { amount: 1145, date: '2026-10-03' }
  ).value;

  const result = dashboard([inv1, inv2Partial, inv3], '2026-10-07');
  // inv1: full balance (1145 cents for PHOTO-LIC with gold tier discount + VAT)
  // inv2: remaining balance after 500 payment
  // inv3: paid, so 0
  assert.ok(result.outstanding > 0);
});

