});

test('lateFee: charges 0.04% per day when overdue', () => {
  const invoice = createIssuedInvoice('C-001', '2026-09-01', 'NET30');
  // Due date is 2026-10-01, check on 2026-10-11 (10 days overdue)
  // Should calculate: balanceDue * 0.0004 * 10
  const fee = lateFee(invoice, '2026-10-11');
  assert.ok(fee >= 0);
  assert.equal(Number.isInteger(fee), true);
});

test('lateFee: calculates correctly for large overdue amount', () => {
  const created = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-09-01',
    lines: [
      { sku: 'LOGO-PACK', qty: 1 }, // 120000 cents with 0% discount, no VAT yet
    ],
    terms: 'NET30',
  });
  const invoice = issueInvoice(created.value, []).value;
  // Due date is 2026-10-01, check on 2026-10-21 (20 days overdue)
  // Balance due: 120000 cents + VAT = 145200 cents
  // Late fee = 145200 * 0.0004 * 20 = 1161.6 → 1162
  const fee = lateFee(invoice, '2026-10-21');
  assert.equal(typeof fee, 'number');
  assert.ok(fee > 0);
});

